const data = $input.first().json;
const rawLogs = data.rawLogs;

if (typeof rawLogs !== "string" || !rawLogs.trim()) {
  throw new Error("Missing rawLogs in Parse SSH Logs input.");
}

const counts = {};

for (const line of rawLogs.split(/\r?\n/)) {
  if (!/Failed password/i.test(line)) continue;

  const match = line.match(
    /Failed password for (?:invalid user )?(\S+) from ((?:\d{1,3}\.){3}\d{1,3})/
  );

  if (!match) continue;

  const username = match[1];
  const ip = match[2];

  if (!counts[ip]) {
    counts[ip] = {
      tag: "NGP-008",
      ip,
      failedCount: 0,
      usernames: []
    };
  }

  counts[ip].failedCount++;
  counts[ip].usernames.push(username);
}

return Object.values(counts).map(item => ({
  json: {
    tag: item.tag,
    ip: item.ip,
    failedCount: item.failedCount,
    usernames: [...new Set(item.usernames)],
    flagged: item.failedCount >= 4,
    verdict: item.failedCount >= 4
      ? "SUSPICIOUS SSH ACTIVITY"
      : "NORMAL"
  }
}));

const crypto = require("crypto");

// Get the AI classification result
const aiResult = $input.first().json;

// Get the original SSH evidence from the parser
const evidence = $("extract ssh login data").first().json;

// Create timestamp
const timestamp = new Date().toISOString();

// Build the audit record
const auditRecord = {
  tag: evidence.tag,
  timestamp: timestamp,
  ip: evidence.ip,
  failedCount: evidence.failedCount,
  usernames: evidence.usernames,
  flagged: evidence.flagged,
  detectionVerdict: evidence.verdict,
  aiDecision: aiResult.output ?? aiResult
};

// Convert the record to a consistent JSON string
const canonicalRecord = JSON.stringify(auditRecord);

// Generate SHA-256 hash
const sha256 = crypto
  .createHash("sha256")
  .update(canonicalRecord)
  .digest("hex");

// Return the audit record and hash
return [
  {
    json: {
      ...auditRecord,
      sha256: sha256
    }
  }
];
